const { execFileSync } = require('child_process');

// gvm-cli recibe el XML como un unico argumento (arreglo de argumentos, sin
// shell): ningun caracter del XML puede interpretarse como una orden.
const GVM_CLI = '/home/node/gvm-env/bin/gvm-cli';
const GMP_ARGS = ['--gmp-username', 'admin', '--gmp-password', 'admin123', 'socket', '--socketpath', '/run/gvmd/gvmd.sock', '--xml'];
const UUID = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/;

// Alcance de V3: solo redes privadas (RFC 1918).
const OCTET = '(?:25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)';
const IPV4 = new RegExp(`^${OCTET}(?:\\.${OCTET}){3}$`);
const isPrivateIp = (ip) => {
  if (typeof ip !== 'string' || !IPV4.test(ip)) return false;
  const [a, b] = ip.split('.').map(Number);
  return a === 10 || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168);
};
const isAllowedIp = isPrivateIp;

// Perfiles de escaneo admitidos (feed Community): los dos que ofrecen el
// Launcher y la app. Cualquier otro valor de ?scan_config= se rechaza.
const SCAN_CONFIGS = [
  '8715c877-47a0-438d-98a3-27c7a6ab2196', // Discovery
  'daba56c8-73ec-11df-a475-002264764cea', // Full and fast
];

// 1. Get the previous output (Target Creation Result)
const prevOutput = items[0].json.stdout;

// 2. Extract the Target ID using Regex
const match = prevOutput.match(/id="([^"]+)"/);
const targetId = match ? match[1] : null;

if (!targetId || !UUID.test(targetId)) {
  throw new Error("Could not find Target ID in previous output");
}

// 3. Get the IP list from the earlier 'Code' node
const ipObjetivo = $('Code').first().json.ip_objetivo;
if (typeof ipObjetivo !== 'string' || !ipObjetivo.split(', ').every(isAllowedIp)) {
  throw new Error('CreateTask: la lista de hosts no es una lista de IPv4 privadas');
}

// 4. Read scan config from launcher (passed as webhook query param)
// Scan config from webhook query param, or Full & Fast default for scheduled runs
let configId;
for (const hook of ['Webhook']) {
  try {
    configId = $(hook).first().json.query?.scan_config;
  } catch (e) {
    configId = undefined;
  }
  if (configId !== undefined && configId !== '') break;
}
if (configId === undefined || configId === '') {
  configId = 'daba56c8-73ec-11df-a475-002264764cea';
} else if (!SCAN_CONFIGS.includes(configId)) {
  throw new Error('CreateTask: scan_config no es uno de los perfiles admitidos');
}

// 5. Construct Command
const xml = `<create_task><name>Scan ${ipObjetivo}</name><config id='${configId}'/><target id='${targetId}'/><scanner id='08b69003-5fc2-4037-a479-93b440211c73'/></create_task>`;

try {
  const stdout = execFileSync(GVM_CLI, [...GMP_ARGS, xml]).toString();
  return [{ json: { stdout } }];
} catch (error) {
