// gvm-cli recibe el XML como un unico argumento (arreglo de argumentos, sin
// shell): ningun caracter del XML puede interpretarse como una orden.
const GVM_CLI = '/home/node/gvm-env/bin/gvm-cli';
const GMP_ARGS = ['--gmp-username', 'admin', '--gmp-password', 'admin123', 'socket', '--socketpath', '/run/gvmd/gvmd.sock', '--xml'];
const UUID = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/;

// Alcance de V3: solo redes privadas (RFC 1918).
const OCTET = '(?:25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)';
const IPV4 = new RegExp(`^${OCTET}(?:\\.${OCTET}){3}$`);
const isPrivateIp = (ip) => {
  if (typeof ip !== 'string' || !IPV4.test(ip)) return false;
  const [a, b] = ip.split('.').map(Number);
  return a === 10 || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168);
};

// 1. Get data from previous node
const hosts = items[0].json.all_ips;
const count = items[0].json.cantidad_hosts;
const ips = typeof hosts === 'string' ? hosts.split(', ') : [];
if (ips.length === 0 || !ips.every(isPrivateIp)) {
  throw new Error('CreateTarget: la lista de hosts no es una lista de IPv4 privadas');
}
if (!Number.isInteger(count) || count !== ips.length) {
  throw new Error('CreateTarget: la cantidad de hosts no coincide con la lista');
}
const now = new Date().toISOString();

// 2. Construct Command
const xml = `<create_target><name>Target Masivo (${count} hosts) - ${now}</name><hosts>${ips.join(', ')}</hosts><port_list id='33d0cd82-57c6-11e1-8ed1-406186ea4fc5'/></create_target>`;

try {
  const stdout = execFileSync(GVM_CLI, [...GMP_ARGS, xml]).toString();
  return [{ json: { stdout } }];
} catch (error) {
  throw new Error(error.message);
}

// 1. Capturamos la salida de Nmap
const nmapData = items[0].json.nmaprun;

// 2. CONFIGURACIÓN: Lista Negra (IPs que NO queremos escanear)
// Infraestructura de lab-net que no es un activo: gateway/reservadas (.1, .2) y
// ospd-openvas (.3). Las 192.168.122.x son de la red historica del prototipo.
const ipsIgnoradas = ["172.20.0.1", "172.20.0.2", "172.20.0.3", "192.168.122.1", "192.168.122.2", "192.168.122.79"];

// --- VERIFICACIÓN INICIAL ---
if (!nmapData || !nmapData.host) {
  return [{
    json: { all_ips: "", ip_objetivo: "", cantidad_hosts: 0, encontrados: false, error: "Nmap no devolvió datos" }
  }];
}

// 3. Normalizamos los hosts
let hostsArray = nmapData.host;
if (!Array.isArray(hostsArray)) {
  hostsArray = [hostsArray];
}

const ipsValidas = [];

// 4. Procesamos y filtramos
for (const host of hostsArray) {
  // Solo si la máquina responde ('up')
  if (host.status && host.status.state === 'up') {
    let ip = "";
    if (Array.isArray(host.address)) {
      const ipv4 = host.address.find(addr => addr.addrtype === 'ipv4');
      ip = ipv4 ? ipv4.addr : host.address[0].addr;
    } else {
      ip = host.address.addr;
    }

    // 🔥 FILTRO DE EXCLUSIÓN 🔥
    if (ip && !ipsIgnoradas.includes(ip)) {
      ipsValidas.push(ip);
    }
  }
}

// 5. RESPUESTA FINAL
if (ipsValidas.length === 0) {
  return [{
    json: {
      all_ips: "",
      ip_objetivo: "",
      cantidad_hosts: 0,
      encontrados: false,
      mensaje: "No se encontraron hosts nuevos (todos fueron ignorados o no responden)."
    }
  }];
}

const listaFinal = ipsValidas.join(", ");

return [{
  json: {
    all_ips: listaFinal,        
    ip_objetivo: listaFinal,    
    cantidad_hosts: ipsValidas.length,
    encontrados: true
  }
}];

