const POLL_INTERVAL = 60000; // 60 segundos en ms

for (let i = 0; i < MAX_ATTEMPTS; i++) {
  const { stdout: output } = await gmp(`<get_tasks task_id='${taskId}'/>`);
  const statusMatch = output.match(/<status>([^<]+)<\/status>/);
  const status = statusMatch ? statusMatch[1] : 'Unknown';

  if (status === 'Done') {
    return [{ json: { stdout: $('StartTask').first().json.stdout } }];
  }

  if (status === 'Stopped' || status === 'Interrupted') {
    throw new Error(`El escaneo terminó con estado inesperado: ${status}`);
  }

  await sleep(POLL_INTERVAL);
}

throw new Error('El escaneo superó el tiempo máximo de espera (90 minutos)');

