const createTargetOutput = $('CreateTarget').first().json.stdout;
const targetMatch = createTargetOutput.match(/id=\"([^\"]+)\"/);
const targetId = targetMatch && UUID.test(targetMatch[1]) ? targetMatch[1] : null;

const run = (xml) => {
  try { execFileSync(GVM_CLI, [...GMP_ARGS, xml]); } catch(e) {}
};

if (taskId) run(`<delete_task task_id='${taskId}' ultimate='0'/>`);
if (targetId) run(`<delete_target target_id='${targetId}'/>`);

return [{ json: { cleaned: true, task_id: taskId, target_id: targetId } }];

const TG_TOKEN = 'TU_TELEGRAM_BOT_TOKEN_AQUI';
const { execFileSync } = require('child_process');
function sendTelegram(chatId, text) {
  const payload = JSON.stringify({ chat_id: String(chatId), text });
  try {
    const out = execFileSync(
      'curl',
      ['-s', '-X', 'POST', `https://api.telegram.org/bot${TG_TOKEN}/sendMessage`,
        '-H', 'Content-Type: application/json', '--data-binary', '@-'],
      { input: payload, maxBuffer: 1024 * 1024 }
    ).toString();
    return JSON.parse(out);
  } catch (e) {
    return { ok: false, description: e.message };
  }
}

const text = '🔍 Escaneo OpenVAS iniciado. Te aviso cuando termine (puede tardar entre 15 y 90 min).';

const result = await sendTelegram('7434106099', text);
return [{ json: result }];
